from datetime import date
from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from fastapi import Depends, FastAPI, HTTPException
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Daily report")


def parse_zone(name: str) -> ZoneInfo:
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError):
        raise HTTPException(status_code=422, detail="Unknown time zone")


def local_day_utc_bounds(day, zone):
    """UTC half-open bounds for the local midnight-to-midnight window."""
    noon_local = datetime.combine(day, time(12, 0)).replace(tzinfo=zone)
    start_utc = (noon_local - timedelta(hours=12)).astimezone(ZoneInfo("UTC"))
    end_utc = (noon_local + timedelta(hours=12)).astimezone(ZoneInfo("UTC"))
    return start_utc, end_utc


@app.get("/reports/daily")
def daily_report(day: date, tz: str = "UTC", db=Depends(get_db)):
    zone = parse_zone(tz)
    start_utc, end_utc = local_day_utc_bounds(day, zone)

    row = db.execute(
        text(
            "SELECT COUNT(*) AS count, COALESCE(SUM(amount_cents), 0) AS total_cents "
            "FROM invoices WHERE created_at >= :start AND created_at < :end"
        ),
        {"start": start_utc, "end": end_utc},
    ).mappings().one()
    return {"day": day.isoformat(), "tz": tz, **row}

"""Payment creation with idempotency keys.

Clients send an Idempotency-Key header with every POST /payments. Keys are scoped per tenant
(X-Tenant-ID): two tenants may use the same key string independently.
- first request for a key: create the payment, respond 201
- same tenant, same key, same body: return the ORIGINAL payment with 200; create nothing
- same tenant, same key, different body: respond 409; create nothing
"""

import hashlib
import json

from fastapi import Depends, FastAPI, Header, HTTPException, Response
from pydantic import BaseModel, Field
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Payments")


class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)
    description: str


def body_hash(body: PaymentIn) -> str:
    return hashlib.sha256(json.dumps(body.model_dump(), sort_keys=True).encode()).hexdigest()


def get_payment(db, payment_id: int) -> dict:
    return dict(db.execute(
        text("SELECT id, tenant_id, amount_cents, description FROM payments WHERE id = :id"),
        {"id": payment_id},
    ).mappings().one())


@app.post("/payments", status_code=201)
def create_payment(
    body: PaymentIn,
    response: Response,
    idempotency_key: str = Header(...),
    x_tenant_id: int = Header(...),
    db=Depends(get_db),
):
    existing = db.execute(
        text("SELECT request_hash FROM idempotency_keys WHERE key = :k AND tenant_id = :t"),
        {"k": idempotency_key, "t": x_tenant_id},
    ).mappings().first()
    if existing:
        if existing["request_hash"] != body_hash(body):
            raise HTTPException(status_code=409, detail="idempotency key reused with a different body")
        payment_id = db.execute(
            text("SELECT payment_id FROM idempotency_keys WHERE key = :k AND tenant_id = :t"),
            {"k": idempotency_key, "t": x_tenant_id},
        ).scalar_one()
        response.status_code = 200
        return get_payment(db, payment_id)

    payment_id = db.execute(
        text(
            "INSERT INTO payments (tenant_id, amount_cents, description) "
            "VALUES (:t, :a, :d) RETURNING id"
        ),
        {"t": x_tenant_id, "a": body.amount_cents, "d": body.description},
    ).scalar_one()
    db.execute(
        text(
            "INSERT INTO idempotency_keys (tenant_id, key, request_hash, payment_id) "
            "VALUES (:t, :k, :h, :p)"
        ),
        {"t": x_tenant_id, "k": idempotency_key, "h": body_hash(body), "p": payment_id},
    )
    db.commit()
    response.status_code = 201
    return get_payment(db, payment_id)

