        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError):
        raise HTTPException(status_code=422, detail="Unknown time zone")


@app.get("/reports/daily")
def daily_report(day: date, tz: str = "UTC", db=Depends(get_db)):
    zone = parse_zone(tz)
    # Compute the UTC range for the given local day in the specified timezone
    # Start at midnight of the day in the target timezone
    start_local = datetime.combine(day, time.min, tzinfo=zone)
    # Convert to UTC
    start_utc = start_local.astimezone(timezone.utc)
    # End is start + 1 day
    end_utc = start_utc + timedelta(days=1)
    row = db.execute(
        text(
            "SELECT COUNT(*) AS count, COALESCE(SUM(amount_cents), 0) AS total_cents "
            "FROM invoices WHERE created_at >= :start AND created_at < :end"
        ),
        {"start": start_utc, "end": end_utc},
    ).mappings().one()
    return {"day": day.isoformat(), "tz": tz, **row}

"""Stock reservations for orders.

- POST /orders/{ref}/reserve reserves every line of an order, or nothing: if any SKU lacks
  stock for the TOTAL quantity requested across all of the order's lines, respond 409 and
  change nothing. Unknown SKUs are 404.
- POST /orders/{ref}/release releases the order's active reservations and returns their
  stock. It is idempotent: releasing an order a second time restores nothing and reports
  released = 0.
"""

from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel, Field
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Inventory")


class Line(BaseModel):
    sku: str
    qty: int = Field(ge=1)


class ReserveRequest(BaseModel):
    lines: list[Line] = Field(min_length=1)


def current_stock(db, sku: str) -> int:
    stock = db.execute(
        text("SELECT stock FROM products WHERE sku = :sku FOR UPDATE"), {"sku": sku}
    ).scalar()
    if stock is None:
        raise HTTPException(status_code=404, detail=f"Unknown SKU {sku}")
    return stock


@app.post("/orders/{order_ref}/reserve")
def reserve(order_ref: str, body: ReserveRequest, db=Depends(get_db)):
    # Aggregate requested quantities per SKU to enforce total stock check across all lines.
    sku_totals: dict[str, int] = {}
    for line in body.lines:
        sku_totals[line.sku] = sku_totals.get(line.sku, 0) + line.qty

    # Verify each SKU has sufficient stock for the aggregated quantity.
    for sku, total_qty in sku_totals.items():
        if current_stock(db, sku) < total_qty:
            raise HTTPException(status_code=409, detail=f"Insufficient stock for {sku}")

    stock = {}
    # Perform updates and create reservations per line (preserving original line granularity).
    for line in body.lines:
        db.execute(
            text("UPDATE products SET stock = stock - :qty WHERE sku = :sku"),
            {"qty": line.qty, "sku": line.sku},
        )
        db.execute(
            text(
                "INSERT INTO reservations (order_ref, sku, qty, status) "
                "VALUES (:ref, :sku, :qty, 'active')"
            ),
            {"ref": order_ref, "sku": line.sku, "qty": line.qty},
        )
        # Record the latest stock for each SKU after updates.
        stock[line.sku] = db.execute(
            text("SELECT stock FROM products WHERE sku = :sku"), {"sku": line.sku}
        ).scalar()
    db.commit()
    return {"order_ref": order_ref, "stock": stock}


@app.post("/orders/{order_ref}/release")
def release(order_ref: str, db=Depends(get_db)):
    # Only release active reservations for the order; idempotent behavior.
    rows = db.execute(
        text(
            "SELECT sku, qty FROM reservations WHERE order_ref = :ref AND status = 'active'"
        ),
        {"ref": order_ref},
    ).mappings().all()
    for row in rows:
        db.execute(
            text("UPDATE products SET stock = stock + :qty WHERE sku = :sku"),
            {"qty": row["qty"], "sku": row["sku"]},
        )
    # Mark released reservations as inactive to prevent double release.
    if rows:
        db.execute(
            text(
                "UPDATE reservations SET status = 'released' WHERE order_ref = :ref AND status = 'active'"
            ),
            {"ref": order_ref},
        )
    db.commit()
    return {"order_ref": order_ref, "released": len(rows)}

