from pydantic import BaseModel, Field
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Invoice splitting")


class SplitRequest(BaseModel):
    payers: int = Field(ge=1, le=20)


@app.post("/invoices/{invoice_id}/split")
def split_invoice(invoice_id: int, body: SplitRequest, db=Depends(get_db)):
    amount = db.execute(
        text("SELECT amount_cents FROM invoices WHERE id = :id"), {"id": invoice_id}
    ).scalar()
    if amount is None:
        raise HTTPException(status_code=404, detail="Invoice not found")

    base_share = amount // body.payers
    remainder = amount % body.payers
    shares = [base_share + 1 if i < remainder else base_share for i in range(body.payers)]
    return {"invoice_id": invoice_id, "amount_cents": amount, "shares": shares}

from typing import Literal

from fastapi import Depends, FastAPI, Header, HTTPException
from pydantic import BaseModel
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Invoices")

class StatusUpdate(BaseModel):
    status: Literal["paid", "pending", "overdue", "void"]


def serialize(row):
    return {**row, "created_at": row["created_at"].isoformat()}


@app.get("/invoices")
def list_invoices(x_tenant_id: int = Header(...), db=Depends(get_db)):
    rows = db.execute(
        text(
            "SELECT id, tenant_id, customer, amount_cents, status, created_at "
            "FROM invoices WHERE tenant_id = :tenant ORDER BY id"
        ),
        {"tenant": x_tenant_id},
    ).mappings().all()
    return [serialize(r) for r in rows]


@app.get("/invoices/{invoice_id}")
def get_invoice(invoice_id: int, x_tenant_id: int = Header(...), db=Depends(get_db)):
    row = db.execute(
        text(
            "SELECT id, tenant_id, customer, amount_cents, status, created_at "
            "FROM invoices WHERE id = :id AND tenant_id = :tenant"
        ),
        {"id": invoice_id, "tenant": x_tenant_id},
    ).mappings().first()
    if row is None:
        raise HTTPException(status_code=404, detail="Invoice not found")
    return serialize(row)


@app.patch("/invoices/{invoice_id}/status")
def update_status(
    invoice_id: int, body: StatusUpdate, x_tenant_id: int = Header(...), db=Depends(get_db)
):
    row = db.execute(
        text(
            "UPDATE invoices SET status = :status WHERE id = :id AND tenant_id = :tenant "
            "RETURNING id, tenant_id, customer, amount_cents, status, created_at"
        ),
        {"status": body.status, "id": invoice_id, "tenant": x_tenant_id},
    ).mappings().first()
    # Only commit if an update occurred (row is not None)
    if row is not None:
        db.commit()
    else:
        # Ensure no commit for no update (no side effects)
        db.rollback()
    if row is None:
        raise HTTPException(status_code=404, detail="Invoice not found")
    return serialize(row)

